/// <reference types="node" />
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { DisplayGeometry, ScreenProjector } from "./core";
import type { GazeProjectionMode } from "../global";
import type { Detection, GazeEstimate } from "./core";

// Generated by tests/gen_projection_fixtures.py from the Python ScreenProjector.
interface FixtureCase {
  config: {
    display: [number, number, number];
    flip_x: boolean;
    flip_y: boolean;
    camera_screen_x: number;
    camera_screen_y: number;
    eye_position_weight_x: number;
    eye_position_weight_y: number;
    camera_fov_deg: number;
    camera_width: number;
    camera_height: number;
  };
  mode: GazeProjectionMode;
  distance_m: number;
  eyes: [number, number, number, number, number, number][];
  estimate: [number, number, number, number, number, number];
  expected_point: [number, number];
  expected_fallback: boolean;
}

const fixture = JSON.parse(
  readFileSync(new URL("../../../tests/fixtures/projection_cases.json", import.meta.url), "utf8")
) as { version: number; cases: FixtureCase[] };

describe("Python/TypeScript ScreenProjector parity", () => {
  it("loads a non-trivial fixture covering every mode and the fallback path", () => {
    expect(fixture.cases.length).toBeGreaterThan(100);
    expect(new Set(fixture.cases.map((c) => c.mode))).toEqual(
      new Set(["legacy", "binocular-screen", "binocular-convergence"])
    );
    expect(fixture.cases.some((c) => c.expected_fallback)).toBe(true);
    expect(fixture.cases.some((c) => c.config.camera_screen_x !== 0.5 && c.config.flip_x)).toBe(true);
  });

  it("reproduces every Python projection result", () => {
    for (const [index, c] of fixture.cases.entries()) {
      const cfg = c.config;
      const projector = new ScreenProjector(
        new DisplayGeometry(...cfg.display),
        cfg.flip_x,
        cfg.flip_y,
        cfg.camera_screen_x,
        cfg.camera_screen_y,
        cfg.eye_position_weight_x,
        cfg.eye_position_weight_y,
        cfg.camera_fov_deg,
        cfg.camera_width,
        cfg.camera_height
      );
      const eyes: Detection[] = c.eyes.map(([classId, score, x1, y1, x2, y2]) => ({ classId, score, x1, y1, x2, y2 }));
      const [yawDeg, pitchDeg, leftYawDeg, leftPitchDeg, rightYawDeg, rightPitchDeg] = c.estimate;
      const estimate: GazeEstimate = { yawDeg, pitchDeg, leftYawDeg, leftPitchDeg, rightYawDeg, rightPitchDeg };
      const result = projector.projectEstimate(c.mode, eyes, estimate, c.distance_m);
      const label = `case ${index} (${c.mode}, cam_x=${cfg.camera_screen_x}, flip_x=${cfg.flip_x})`;
      expect(result.fallbackReason !== undefined, label).toBe(c.expected_fallback);
      expect(result.point[0], label).toBeCloseTo(c.expected_point[0], 9);
      expect(result.point[1], label).toBeCloseTo(c.expected_point[1], 9);
    }
  });
});

describe("ScreenProjector regression fixes", () => {
  const display = new DisplayGeometry(1920, 1080, 31.5);

  it("maps looking into an off-center camera to the camera position", () => {
    for (const camX of [0, 0.2, 0.5, 0.85, 1]) {
      for (const flipX of [true, false]) {
        const projector = new ScreenProjector(display, flipX, true, camX);
        expect(projector.project([320, 240], 0, 0, 0.6)[0]).toBeCloseTo(camX, 9);
      }
    }
  });

  it("keeps binocular-convergence on the screen plane despite vergence error", () => {
    const projector = new ScreenProjector(display, false, false);
    const distanceM = 0.6;
    const half = (0.0315 * projector.focalPx) / distanceM;
    const eyes: Detection[] = [
      { classId: 17, score: 1, x1: 316 - half, y1: 236, x2: 324 - half, y2: 244 },
      { classId: 17, score: 1, x1: 316 + half, y1: 236, x2: 324 + half, y2: 244 }
    ];
    const widthM = display.sizeM[0];
    const originX = widthM * 0.5;
    const targetX = originX + 0.25;
    const yawL = (Math.atan((targetX - (originX - 0.0315)) / distanceM) * 180) / Math.PI;
    const yawR = (Math.atan((targetX - (originX + 0.0315)) / distanceM) * 180) / Math.PI;
    for (const err of [-1.5, 0, 1.5]) {
      const estimate: GazeEstimate = {
        yawDeg: 0,
        pitchDeg: 0,
        leftYawDeg: yawL + err,
        leftPitchDeg: 0,
        rightYawDeg: yawR - err,
        rightPitchDeg: 0
      };
      const result = projector.projectEstimate("binocular-convergence", eyes, estimate, distanceM);
      expect(result.fallbackReason).toBeUndefined();
      expect(Math.abs(result.point[0] - targetX / widthM)).toBeLessThan(0.005);
    }
  });
});
